const body = $input.first().json.body || $input.first().json;
const isV2 = String(body.version || '') === '2';
const user_context = body.user_context || '';

const frozen_data = body.frozen_data || {};

const meta = isV2 && body.client
  ? {
      nom:             body.client.nom            ?? null,
      prenom:          body.client.prenom         ?? null,
      date_naissance:  body.client.date_naissance ?? null,
      sexe:            body.client.sexe           ?? null,
      nir:             body.client.nir            ?? null,
      nombre_enfants:  body.client.enfants        ?? null,
      statut_marital:  body.client.statut_marital ?? frozen_data.meta?.statut_marital ?? null,
    }
  : (frozen_data.meta || {});

const totaux   = body.totaux   ?? frozen_data.totaux   ?? {};
const carriere = body.carriere ?? frozen_data.carriere ?? [];
const alertes  = body.alertes  ?? frozen_data.alertes  ?? [];

const regimes = body.regimes || {
  cipav:          frozen_data.cipav          || {},
  carpimko:       frozen_data.carpimko       || {},
  regimes_points: frozen_data.regimes_points || {},
};

const scenarios_retenus = Array.isArray(body.scenarios_retenus) ? body.scenarios_retenus : [];
const dates_retenues    = Array.isArray(body.dates_retenues)    ? body.dates_retenues    : [];
const calculs_skills    = Array.isArray(body.calculs_skills)    ? body.calculs_skills    : [];
const client_block      = body.client || null;
const frozen_meta       = body.frozen || { locked: !!frozen_data.locked };

const client_id = body.client_id
  || frozen_data.user_id
  || (client_block && client_block.user_id)
  || 0;

let scenarios_override = body.scenarios || null;
if (!scenarios_override && dates_retenues.length > 0) {
  const sortedDates = [...dates_retenues]
    .filter(d => d && d.date)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)));
  if (sortedDates.length > 0) {
    scenarios_override = {};
    const slots = ['H1', 'H2', 'H3'];
    sortedDates.slice(0, 3).forEach((d, i) => {
      scenarios_override[slots[i]] = {
        date_depart: d.date,
        is_progressive: d.type === 'retraite_progressive'
                     || /progressive/i.test(d.label || ''),
      };
    });
  }
}

return [{ json: {
  client_id,
  user_id: client_id,
  meta,
  totaux,
  carriere,
  revenu_souhaite: body.revenu_souhaite || 0,
  scenarios_override,
  frozen_data,
  startTime: Date.now(),
  payload_version: isV2 ? '2' : '1',
  client_block,
  frozen_meta,
  alertes,
  scenarios_retenus,
  dates_retenues,
  calculs_skills,
  regimes,
  user_context,
} }];

// ============================================================================
// CONSTANTES 2025
// ============================================================================
const TAUX_PLEIN = 0.50;
const TAUX_MINIMAL = 0.375;
const DECOTE_PAR_TRIM = 0.0125;
const VALEUR_POINT_AGIRC_2025 = 1.4386;
const VALEUR_POINT_IRCANTEC_2025 = 0.55553;
const VALEUR_POINT_RCI_2025 = 1.351;
const VALEUR_POINT_CIPAV_BASE_2025 = 0.654;
const VALEUR_POINT_CIPAV_COMPL_2025 = 2.89;
const VALEUR_POINT_CARPIMKO_BASE_2025 = 0.586;
const VALEUR_POINT_CARPIMKO_ASV_2025 = 5.45;
const VALEUR_POINT_CARPIMKO_COMPL_2025 = 11.30;
// Tier 1 — régimes simples multi-piliers (CARMF, CARCDSF, CARPV, CAVP, CNBF, MSA, CAVAMAC, CAVOM, CRN, CAVEC).
// Valeurs de point 2025 par défaut (€/pt). Approximations — le consultant peut ajuster via points_officiels[regime] dans frozen_data.
const REGIMES_TIER1_VP_2025 = {
  CARMF:   {base: 0.500,  complementaire: 0.4500, asv: 0.0},
  CARCDSF: {base: 0.500,  complementaire: 0.5800, asv: 5.0000},
  CARPV:   {base: 0.500,  complementaire: 0.6800},
  CAVP:    {base: 0.500,  complementaire: 0.6700},
  CNBF:    {base: 0.500,  complementaire: 1.0000},
  MSA:     {base: 0.500},
  CAVAMAC: {base: 0.500,  complementaire: 0.6300},
  CAVOM:   {base: 0.500,  complementaire: 0.6500},
  CRN:     {base: 0.500,  complementaire: 1.4000},
  CAVEC:   {base: 0.4486, complementaire: 0.9000}
};
const REGIMES_TIER1_DEFAULT_VP = {base: 0.500, complementaire: 0.700, asv: 5.000};
const TAUX_PRELEVEMENT_NET = 0.091;
const AGE_TAUX_PLEIN_AUTO = 67;
const AGE_LEGAL_ANS = 62;  // base; effective age via ageLegalMonths()
const DUREES_REQUISES = {1958:167,1959:167,1960:167,1961:168,1962:169,1963:170,1964:170,1965:170,1966:172,1967:172,1968:172};
// Source : Circulaire Cnav 2026-07 (loi n°2025-1403 du 30/12/2025 — suspension réforme 2023). Effet retraite ≥ 01/09/2026.

const TRIM_BONUS_PAR_ENFANT_MERE = 8;
const TRIM_BONUS_PAR_ENFANT_PERE = 0;
const SEUIL_MAJO_FAMILIALE = 3;
const TAUX_MAJO_FAMILIALE = 0.10;
const PLAFOND_MAJO_AGIRC_MENSUEL = 178.67;

function ageLegalMonths(annee, mois) {
  // Circulaire Cnav 2026-07 (loi n°2025-1403 du 30/12/2025).
  if (annee < 1961 || (annee === 1961 && mois < 9)) return 62 * 12;
  if (annee === 1961) return 62 * 12 + 3;
  if (annee === 1962) return 62 * 12 + 6;
  if (annee === 1963 || annee === 1964) return 62 * 12 + 9;
  if (annee === 1965 && mois < 4) return 62 * 12 + 9;
  if (annee === 1965) return 63 * 12;
  if (annee === 1966) return 63 * 12 + 3;
  if (annee === 1967) return 63 * 12 + 6;
  if (annee === 1968) return 63 * 12 + 9;
  return 64 * 12;
}

function parseDate(s) {
  s = String(s).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return new Date(s + 'T00:00:00');
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) {
    const p = s.split('/');
    return new Date(p[2] + '-' + p[1] + '-' + p[0] + 'T00:00:00');
  }
  return new Date(s);
}

function fmtDate(d) { return d.toISOString().split('T')[0]; }
function getDureeRequise(y, m) { if (y === 1965 && m && m >= 4) return 171; return DUREES_REQUISES[y] || 172; }
function monthsBetween(d1, d2) { return (d2.getFullYear() - d1.getFullYear()) * 12 + (d2.getMonth() - d1.getMonth()); }
function addMonths(d, m) { const r = new Date(d); r.setMonth(r.getMonth() + m); return r; }
function addYears(d, y) { const r = new Date(d); r.setFullYear(r.getFullYear() + y); return r; }

function ageFloat(ddn, ref) {
  let y = ref.getFullYear() - ddn.getFullYear();
  let mo = ref.getMonth() - ddn.getMonth();
  let da = ref.getDate() - ddn.getDate();
  if (da < 0) mo--;
  if (mo < 0) { y--; mo += 12; }
  return y + mo / 12.0 + Math.max(da, 0) / 365.25;
}

function ageYM(ddn, ref) {
  let y = ref.getFullYear() - ddn.getFullYear();
  let mo = ref.getMonth() - ddn.getMonth();
  if (ref.getDate() < ddn.getDate()) mo--;
  if (mo < 0) { y--; mo += 12; }
  return { years: y, months: mo, totalMonths: y * 12 + mo };
}

function trimAtDate(trim, ref, cible) {
  const diff = monthsBetween(ref, cible);
  return trim + Math.max(0, Math.floor(diff / 3));
}

function tauxCnav(trim, duree, age) {
  if (trim >= duree || age >= AGE_TAUX_PLEIN_AUTO) return TAUX_PLEIN;
  const manq = Math.min(duree - trim, 20);
  return Math.max(TAUX_PLEIN - manq * DECOTE_PAR_TRIM, TAUX_MINIMAL);
}

function pensionCnav(sam, taux, trimRg, duree) {
  return Math.round(sam * taux * Math.min(trimRg / duree, 1.0) / 12 * 100) / 100;
}

function dateTauxPlein(ddn, trimTous, ref) {
  const duree = getDureeRequise(ddn.getFullYear(), ddn.getMonth() + 1);
  const manq = Math.max(0, duree - trimTous);
  return addMonths(ref, Math.ceil(manq * 3));
}

function dateAgeLegal(ddn) {
  const m = ageLegalMonths(ddn.getFullYear(), ddn.getMonth() + 1);
  return addMonths(ddn, m);
}

function coeffAgirc(dateDepart, dateTp, age, isProgressive) {
  if (age >= AGE_TAUX_PLEIN_AUTO || isProgressive) return {coeff:1.00, duree:0};
  if (dateDepart >= addMonths(dateTp, 12)) return {coeff:1.00, duree:0};
  return {coeff:0.90, duree:36};
}

function readPoints() {
  for (let i = 0; i < arguments.length; i++) {
    const v = arguments[i];
    if (v == null) continue;
    if (typeof v === 'number' && !isNaN(v)) return v;
    if (typeof v === 'string') {
      const n = parseFloat(v);
      if (!isNaN(n)) return n;
    }
    if (typeof v === 'object') {
      const sub = (v.total_points != null) ? v.total_points :
                  (v.points_total != null) ? v.points_total :
                  (v.points_base  != null) ? v.points_base  :
                  (v.points       != null) ? v.points       :
                  (v.value        != null) ? v.value        : null;
      if (sub != null) {
        const n = typeof sub === 'number' ? sub : parseFloat(sub);
        if (!isNaN(n)) return n;
      }
    }
  }
  return 0;
}

function readVp(obj, key, fallback) {
  if (!obj || typeof obj !== 'object') return fallback;
  const v = obj[key];
  if (v == null) return fallback;
  const n = typeof v === 'number' ? v : parseFloat(v);
  return isNaN(n) ? fallback : n;
}

function applyMajoMensuelle(pensionMensuelle, majoPct, plafondMensuel) {
  if (!majoPct || majoPct <= 0 || pensionMensuelle <= 0) return pensionMensuelle;
  const supplement = pensionMensuelle * majoPct;
  const supplPlafonne = plafondMensuel != null ? Math.min(supplement, plafondMensuel) : supplement;
  return pensionMensuelle + supplPlafonne;
}


// FIX #2 (2026-05-13) — Surcote CNAV : +1.25%/trim cotisé après âge légal au-delà
// de la durée requise. Approximation pragmatique : compte les trim. acquis projetés
// au-delà de duree_requise, à condition que la date départ soit >= dateAgeLegal.
function calculSurcoteCoef(trimRg_at_depart, duree_requise, dateDepart, dateAgeLegal_dt) {
  if (dateDepart < dateAgeLegal_dt) return { coef: 1.00, trim: 0 };
  if (trimRg_at_depart <= duree_requise) return { coef: 1.00, trim: 0 };
  // monthsAfterLegal en mois, traduit en trim
  const monthsAfterLegal = monthsBetween(dateAgeLegal_dt, dateDepart);
  const trimAfterLegal = Math.max(0, Math.floor(monthsAfterLegal / 3));
  // trim surcote = min(trim au-dessus durée, trim cotisés après âge légal)
  const trimSurplusTotal = trimRg_at_depart - duree_requise;
  const trimSurcote = Math.min(trimSurplusTotal, trimAfterLegal);
  const coef = Math.round((1 + trimSurcote * 0.0125) * 10000) / 10000;
  return { coef, trim: trimSurcote };
}

function calculScenario(code, ddStr, ddn, ref, dtp, sam, trimRg, trimTous, duree,
    agPts, agVp, ircPts, ircVp, rciPts, rciVp,
    cipavBasePts, cipavBaseVp, cipavComplPts, cipavComplVp,
    carpimkoBasePts, carpimkoBaseVp, carpimkoAsvPts, carpimkoAsvVp, carpimkoComplPts, carpimkoComplVp,
    regimesT1,
    isProg, majoFamPct, ratesPerYear,
    vplrRachatTaxEt, vplrRachatTaxSeul, vplrCoutParTrim, vplrOption) {
  const dd = parseDate(ddStr);
  const trRg = trimAtDate(trimRg, ref, dd);
  const trTous = trimAtDate(trimTous, ref, dd);
  const age = ageYM(ddn, dd);
  const ageF = ageFloat(ddn, dd);
  // VPLR rachat — application conditionnelle PER SCENARIO :
  // - Si le scenario est déjà au taux plein automatique (≥67 ans), inutile.
  // - Sinon on applique seulement la fraction "utile" (qui amène trTous à
  //   duree_requise ; la portion en surplus est gaspillée).
  const _rachatTotal = (vplrRachatTaxEt || 0) + (vplrRachatTaxSeul || 0);
  const _ageAtTpAuto = ageF >= AGE_TAUX_PLEIN_AUTO;
  const _trimManquantsTaux = _ageAtTpAuto ? 0 : Math.max(0, duree - trTous);
  const _trimManquantsRatio = Math.max(0, duree - trRg);
  // Pour le taux : tout type de rachat compte, mais seulement à hauteur de ce qui manque.
  const _rachatUtileTaux = Math.min(_rachatTotal, _trimManquantsTaux);
  // Pour le ratio (proratisation) : seul taux_et_duree compte, plafonné aux trim. manquants RG.
  const _rachatUtileRatio = Math.min(vplrRachatTaxEt || 0, _trimManquantsRatio);
  const trTousEff_vplr = trTous + _rachatUtileTaux;
  const trRgEff_vplr   = trRg   + _rachatUtileRatio;
  const _vplrRachatApplique = {
    nb_trim_demande: _rachatTotal,
    nb_trim_utile_taux: _rachatUtileTaux,
    nb_trim_utile_ratio: _rachatUtileRatio,
    nb_trim_utile: Math.max(_rachatUtileTaux, _rachatUtileRatio),
    cout_total_utile: Math.round(((vplrCoutParTrim || 0) * Math.max(_rachatUtileTaux, _rachatUtileRatio)) * 100) / 100,
    cout_par_trimestre: vplrCoutParTrim || 0,
    option: vplrOption || 'taux_et_duree',
    utile: (_rachatUtileTaux > 0 || _rachatUtileRatio > 0),
    raison_si_inutile: _rachatTotal > 0 && !(_rachatUtileTaux > 0 || _rachatUtileRatio > 0)
      ? (_ageAtTpAuto ? "Taux plein automatique à 67 ans déjà acquis" : "Trimestres acquis déjà ≥ durée requise")
      : null
  };
  const tc = tauxCnav(trTousEff_vplr, duree, ageF);
  const decTr = (trTousEff_vplr < duree && ageF < AGE_TAUX_PLEIN_AUTO) ? Math.max(0, Math.min(duree - trTousEff_vplr, 20)) : 0;
  const ca = coeffAgirc(dd, dtp, ageF, isProg);

  const monthsExtra = Math.max(0, monthsBetween(ref, dd));
  const yearsExtra = monthsExtra / 12;
  const r = ratesPerYear || {};
  const agPtsScn = Math.round((agPts + (r.agirc || 0) * yearsExtra) * 100) / 100;
  const ircPtsScn = Math.round((ircPts + (r.ircantec || 0) * yearsExtra) * 100) / 100;
  const rciPtsScn = Math.round((rciPts + (r.rci || 0) * yearsExtra) * 100) / 100;
  const cipavBasePtsScn = Math.round((cipavBasePts + (r.cipav_base || 0) * yearsExtra) * 100) / 100;
  const cipavComplPtsScn = Math.round((cipavComplPts + (r.cipav_compl || 0) * yearsExtra) * 100) / 100;
  const carpimkoBasePtsScn = Math.round((carpimkoBasePts + (r.carpimko_base || 0) * yearsExtra) * 100) / 100;
  const carpimkoAsvPtsScn = Math.round((carpimkoAsvPts + (r.carpimko_asv || 0) * yearsExtra) * 100) / 100;
  const carpimkoComplPtsScn = Math.round((carpimkoComplPts + (r.carpimko_compl || 0) * yearsExtra) * 100) / 100;

  // FIX #2 — surcote CNAV
  const _dateAgeLegal = dateAgeLegal(ddn);
  const _surcote = calculSurcoteCoef(trRgEff_vplr, duree, dd, _dateAgeLegal);
  const pcRawSansSurcote = pensionCnav(sam, tc, trRgEff_vplr, duree);
  const pcRaw = Math.round(pcRawSansSurcote * _surcote.coef * 100) / 100;
  const paRaw = Math.round(agPtsScn * agVp * ca.coeff / 12 * 100) / 100;
  const piRaw = Math.round(ircPtsScn * ircVp / 12 * 100) / 100;
  const prRaw = Math.round(rciPtsScn * rciVp / 12 * 100) / 100;
  const pcbRaw = Math.round(cipavBasePtsScn * cipavBaseVp / 12 * 100) / 100;
  const pccRaw = Math.round(cipavComplPtsScn * cipavComplVp / 12 * 100) / 100;
  const pckbRaw = Math.round(carpimkoBasePtsScn * carpimkoBaseVp / 12 * 100) / 100;
  const pckaRaw = Math.round(carpimkoAsvPtsScn * carpimkoAsvVp / 12 * 100) / 100;
  const pckcRaw = Math.round(carpimkoComplPtsScn * carpimkoComplVp / 12 * 100) / 100;
  // Boucle générique Tier 1 : calcule une pension pour chaque (régime × pilier) dans regimes_points.
  // Permet de gérer automatiquement CAVEC, CARMF, CARCDSF, CARPV, CAVP, CNBF, MSA, CAVAMAC, CAVOM, CRN
  // et tout futur régime ajouté à frozen_data.regimes_points sans modifier le moteur.
  const tier1PensionsBrut = {};
  let tier1BrutTotal = 0;
  for (const regimeCode of Object.keys(regimesT1 || {})) {
    const piliers = regimesT1[regimeCode] || {};
    const vpReg = REGIMES_TIER1_VP_2025[regimeCode] || {};
    for (const pilierKey of Object.keys(piliers)) {
      const pts = parseFloat(piliers[pilierKey]) || 0;
      if (pts === 0) continue;
      const vp = vpReg[pilierKey] != null ? vpReg[pilierKey] : (REGIMES_TIER1_DEFAULT_VP[pilierKey] || 0.5);
      const projKey = regimeCode + '_' + pilierKey;
      const ptsScn = Math.round((pts + ((r || {})[projKey] || 0) * yearsExtra) * 100) / 100;
      const pensionMens = Math.round(ptsScn * vp / 12 * 100) / 100;
      tier1PensionsBrut[projKey] = { points: ptsScn, valeur_point: vp, pension_mensuelle_brut: pensionMens };
      tier1BrutTotal += pensionMens;
    }
  }
  tier1BrutTotal = Math.round(tier1BrutTotal * 100) / 100;

  const brutAvantMajo = Math.round((pcRaw + paRaw + piRaw + prRaw + pcbRaw + pccRaw + pckbRaw + pckaRaw + pckcRaw + tier1BrutTotal) * 100) / 100;

  const pc = Math.round(applyMajoMensuelle(pcRaw, majoFamPct, null) * 100) / 100;
  const pa = Math.round(applyMajoMensuelle(paRaw, majoFamPct, PLAFOND_MAJO_AGIRC_MENSUEL) * 100) / 100;
  const pi = Math.round(applyMajoMensuelle(piRaw, majoFamPct, null) * 100) / 100;
  const pr = Math.round(applyMajoMensuelle(prRaw, majoFamPct, null) * 100) / 100;
  const pcb = Math.round(applyMajoMensuelle(pcbRaw, majoFamPct, null) * 100) / 100;
  const pcc = Math.round(applyMajoMensuelle(pccRaw, majoFamPct, null) * 100) / 100;
  const pckb = Math.round(applyMajoMensuelle(pckbRaw, majoFamPct, null) * 100) / 100;
  const pcka = Math.round(applyMajoMensuelle(pckaRaw, majoFamPct, null) * 100) / 100;
  const pckc = Math.round(applyMajoMensuelle(pckcRaw, majoFamPct, null) * 100) / 100;

  // Tier 1 : on applique la majo familiale sur chaque pension (sans plafond AGIRC)
  let tier1BrutMajore = 0;
  const tier1Result = {};
  for (const k of Object.keys(tier1PensionsBrut)) {
    const raw = tier1PensionsBrut[k].pension_mensuelle_brut;
    const majoree = Math.round(applyMajoMensuelle(raw, majoFamPct, null) * 100) / 100;
    tier1Result[k] = { ...tier1PensionsBrut[k], pension_mensuelle_majoree: majoree };
    tier1BrutMajore += majoree;
  }
  tier1BrutMajore = Math.round(tier1BrutMajore * 100) / 100;
  const brut = Math.round((pc + pa + pi + pr + pcb + pcc + pckb + pcka + pckc + tier1BrutMajore) * 100) / 100;
  const prelev = Math.round(brut * TAUX_PRELEVEMENT_NET * 100) / 100;
  const net = Math.round((brut - prelev) * 100) / 100;
  const majoImpact = Math.round((brut - brutAvantMajo) * 100) / 100;

  const ratioProrata = Math.min(trRgEff_vplr / duree, 1.0);

  return {
    code, date_depart: ddStr,
    age_depart_annees: age.years, age_depart_mois: age.months,
    trimestres_rg_at_depart: trRgEff_vplr, trimestres_acquis_tous: trTousEff_vplr, trimestres_rg_brut: trRg, trimestres_tous_brut: trTous, vplr_rachat_applique: _vplrRachatApplique,
    duree_requise: duree,
    surcote_trim: _surcote.trim,
    surcote_coef: _surcote.coef,
    surcote_montant_mensuel: Math.round((pcRaw - pcRawSansSurcote) * 100) / 100,
    taux_cnav: Math.round(tc * 100 * 100) / 100,
    decote_pct: Math.round(decTr * DECOTE_PAR_TRIM * 100 * 100) / 100,
    ratio_prorata: Math.round(ratioProrata * 10000) / 10000,
    pension_cnav_mensuelle: pc,
    pension_cnav_avant_majo: pcRaw,
    coefficient_agirc: ca.coeff, agirc_coeff_duree_mois: ca.duree,
    pension_agirc_mensuelle: pa,
    pension_agirc_avant_majo: paRaw,
    pension_ircantec_mensuelle: pi,
    pension_ircantec_avant_majo: piRaw,
    pension_rci_mensuelle: pr,
    pension_rci_avant_majo: prRaw,
    pension_cipav_base_mensuelle: pcb,
    pension_cipav_base_avant_majo: pcbRaw,
    pension_cipav_compl_mensuelle: pcc,
    pension_cipav_compl_avant_majo: pccRaw,
    pension_carpimko_base_mensuelle: pckb,
    pension_carpimko_base_avant_majo: pckbRaw,
    pension_carpimko_asv_mensuelle: pcka,
    pension_carpimko_asv_avant_majo: pckaRaw,
    pension_carpimko_compl_mensuelle: pckc,
    pension_carpimko_compl_avant_majo: pckcRaw,
    carpimko_base_points_projetes: carpimkoBasePtsScn,
    carpimko_asv_points_projetes: carpimkoAsvPtsScn,
    carpimko_compl_points_projetes: carpimkoComplPtsScn,
    pensions_tier1: tier1Result,
    pension_tier1_brute_mensuelle: tier1BrutMajore,
    pension_tier1_avant_majo_mensuelle: Math.round(tier1BrutTotal * 100) / 100,
    pension_brut_avant_majo_mensuelle: brutAvantMajo,
    pension_totale_brute: brut,
    prelevements_sociaux_mensuel: prelev,
    pension_totale_nette: net,
    majo_fam_pct: majoFamPct || 0,
    majo_impact_mensuel: majoImpact,
    mois_supplementaires_travailles: monthsExtra,
