function projection20ans(scenarios, ref, inflation) {
  const horizons = [1,2,3,5,8,10,12,15,18,20];
  return horizons.map(annees => {
    const row = {horizon: annees, annee: ref.getFullYear() + annees};
    ['H1','H2','H3'].forEach(code => {
      if (!scenarios[code]) { row[code+'_cumul_nominal']=null; row[code+'_cumul_reel']=null; row[code+'_mensuel_reel']=null; return; }
      const sc = scenarios[code];
      const dd = parseDate(sc.date_depart);
      const fin = addYears(ref, annees);
      let cum = 0, moisDep = 0, cur = new Date(ref);
      while (cur < fin) {
        if (cur >= dd) {
          const cm = (sc.agirc_coeff_duree_mois > 0 && moisDep < sc.agirc_coeff_duree_mois) ? 0.90 : 1.00;
          const agAdj = sc.coefficient_agirc < 1 ? sc.pension_agirc_mensuelle * (cm / sc.coefficient_agirc) : sc.pension_agirc_mensuelle;
          const others = (sc.pension_cnav_mensuelle || 0) + (sc.pension_ircantec_mensuelle || 0) + (sc.pension_rci_mensuelle || 0)
            + (sc.pension_cipav_base_mensuelle || 0) + (sc.pension_cipav_compl_mensuelle || 0);
          const brutMois = agAdj + others;
          const netMois = Math.round(brutMois * (1 - TAUX_PRELEVEMENT_NET) * 100) / 100;
          cum += netMois; moisDep++;
        }
        cur = addMonths(cur, 1);
      }
      row[code+'_cumul_nominal'] = Math.round(cum * 100) / 100;
      row[code+'_cumul_reel'] = Math.round(cum / Math.pow(1 + inflation, annees) * 100) / 100;
      row[code+'_mensuel_reel'] = Math.round((sc.pension_totale_nette || 0) / Math.pow(1 + inflation, annees) * 100) / 100;
    });
