  const d1 = parseDate(h1.date_depart), d3 = parseDate(h3.date_depart);
  const n1 = h1.pension_totale_nette, n3 = h3.pension_totale_nette;
  if (d3 <= d1 && n3 >= n1) return {applicable:true, immediat:true, mois:0, date:h3.date_depart, explication:'H3 superieur a H1 des le depart.'};
  const moisGap = Math.max(0, monthsBetween(d1, d3));
  const capital = Math.round(n1 * moisGap * 100) / 100;
  const gain = Math.round((n3 - n1) * 100) / 100;
  if (gain <= 0) return {applicable:true, immediat:false, mois:null, date:null, explication:'H3 sans gain mensuel vs H1.', capital_perdu:capital, gain_mensuel:gain};
  const bm = Math.ceil(capital / gain);
