  const ratioCapped = Math.min(ratio, 1.0);
  const ratioTxt = ratio > 1.0
    ? 'min(' + trimRg + '/' + duree + '; 1) = 1,000'
    : '(' + trimRg + '/' + duree + ') = ' + fmt3(ratioCapped);
  return fmtInt(sam) + ' × ' + fmt3(taux) + ' × ' + ratioTxt + majoFmt;
