           .join(choixConsultantBlock + '<h2>2. Tableau Comparatif Détaillé</h2>');

const RAW_KEYS = new Set(['H1_BLOCK','H2_BLOCK','H3_ROWS','ANALYSE_SITUATION','NOTE_CONSULTANT','PROJECTION_TABLE','MAJO_DETAIL_BLOCK']);
Object.entries(ctx).forEach(([key, val]) => {
