const body = $input.first().json.body || $input.first().json;
const isV2 = String(body.version || '') === '2';
const user_context = body.user_context || '';

const frozen_data = body.frozen_data || {};

const meta = isV2 && body.client
  ? {
      nom:             body.client.nom            ?? null,
      prenom:          body.client.prenom         ?? null,
      date_naissance:  body.client.date_naissance ?? null,
      sexe:            body.client.sexe           ?? null,
      nir:             body.client.nir            ?? null,
      nombre_enfants:  body.client.enfants        ?? null,
    }
  : (frozen_data.meta || {});

const totaux   = body.totaux   ?? frozen_data.totaux   ?? {};
const carriere = body.carriere ?? frozen_data.carriere ?? [];
const alertes  = body.alertes  ?? frozen_data.alertes  ?? [];

const regimes = body.regimes || {
  cipav:          frozen_data.cipav          || {},
  carpimko:       frozen_data.carpimko       || {},
  regimes_points: frozen_data.regimes_points || {},
};

const scenarios_retenus = Array.isArray(body.scenarios_retenus) ? body.scenarios_retenus : [];
const dates_retenues    = Array.isArray(body.dates_retenues)    ? body.dates_retenues    : [];
const calculs_skills    = Array.isArray(body.calculs_skills)    ? body.calculs_skills    : [];
const client_block      = body.client || null;
const frozen_meta       = body.frozen || { locked: !!frozen_data.locked };

const client_id = body.client_id
  || frozen_data.user_id
  || (client_block && client_block.user_id)
  || 0;

let scenarios_override = body.scenarios || null;
if (!scenarios_override && dates_retenues.length > 0) {
  const sortedDates = [...dates_retenues]
    .filter(d => d && d.date)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)));
  if (sortedDates.length > 0) {
    scenarios_override = {};
    const slots = ['H1', 'H2', 'H3'];
    sortedDates.slice(0, 3).forEach((d, i) => {
      scenarios_override[slots[i]] = {
        date_depart: d.date,
        is_progressive: d.type === 'retraite_progressive'
                     || /progressive/i.test(d.label || ''),
      };
    });
  }
}

return [{ json: {
