return [{json: {calcul: result, meta, totaux, client_id: prep.client_id || frozen_data.user_id || 0}}];

const calc = $input.first().json.calcul || {};
const meta = $input.first().json.meta || {};
const totaux = $input.first().json.totaux || {};
const client_id = $input.first().json.client_id || $('PREP PAYLOAD').first().json.client_id;

const sc = calc.scenarios || {};
const H1 = sc.H1 || {};
const H2 = sc.H2 || {};
const H3 = sc.H3 || {};

const fmt = (v) => v != null ? Number(v).toLocaleString('fr-FR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '0,00';
const fmtInt = (v) => v != null ? Math.round(Number(v)).toLocaleString('fr-FR') : '0';
const fmt3 = (v) => v != null ? Number(v).toLocaleString('fr-FR', {minimumFractionDigits: 3, maximumFractionDigits: 3}) : '0,000';
const fmt4 = (v) => v != null ? Number(v).toLocaleString('fr-FR', {minimumFractionDigits: 4, maximumFractionDigits: 4}) : '0,0000';

const fmtDateLong = (d) => {
  if (!d) return '—';
  try {
    const dt = d.includes('/') ? (() => { const p = d.split('/'); return new Date(p[2]+'-'+p[1]+'-'+p[0]+'T00:00:00'); })() : new Date(d+'T00:00:00');
    return dt.toLocaleDateString('fr-FR', {month: 'long', year: 'numeric'});
  } catch { return d; }
};

const fmtDateCourt = (d) => {
  if (!d) return '—';
  try {
    const dt = d.includes('/') ? (() => { const p = d.split('/'); return new Date(p[2]+'-'+p[1]+'-'+p[0]+'T00:00:00'); })() : new Date(d+'T00:00:00');
    return dt.toLocaleDateString('fr-FR');
  } catch { return d; }
};

const ddnRaw = meta.date_naissance || meta.ddn || '';
const ddnFormatted = fmtDateCourt(ddnRaw);

const samAnnuel = parseFloat(totaux.sam || totaux.sam_cnav || 0);

const _po = (totaux.points_officiels && typeof totaux.points_officiels === 'object') ? totaux.points_officiels : {};
const readNum = (v) => {
  if (v == null) return 0;
  if (typeof v === 'number') return isNaN(v) ? 0 : v;
  if (typeof v === 'object') {
    const sub = v.total_points != null ? v.total_points : (v.points_total != null ? v.points_total : (v.points_base != null ? v.points_base : (v.points != null ? v.points : v.value)));
    return readNum(sub);
  }
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
};
const ag_pts = readNum(_po.agirc_arrco) || readNum(_po.agirc) || readNum(totaux.agirc_points) || readNum(totaux.points_agirc);
const ag_vp = (_po.agirc_arrco && _po.agirc_arrco.valeur_point) || 1.4386;
const ir_pts = readNum(_po.ircantec) || readNum(totaux.ircantec_points);
const ir_vp = (_po.ircantec && _po.ircantec.valeur_point) || 0.55553;
const rc_pts = readNum(_po.rci) || readNum(totaux.rci_points);
const rc_vp = (_po.rci && _po.rci.valeur_point) || 1.351;
const cipav_base_pts = (_po.cipav && _po.cipav.points_base) || readNum(_po.cipav_base) || 0;
const cipav_base_vp = (_po.cipav && _po.cipav.valeur_point_base) || 0.654;
const cipav_compl_pts = (_po.cipav && _po.cipav.points_complementaire) || readNum(_po.cipav_complementaire) || 0;
const cipav_compl_vp = (_po.cipav && _po.cipav.valeur_point_complementaire) || 2.89;
const carpimko_base_vp   = (_po.carpimko && _po.carpimko.valeur_point_base)           || 0.586;
const carpimko_asv_vp    = (_po.carpimko && _po.carpimko.valeur_point_asv)            || 5.45;
const carpimko_compl_vp  = (_po.carpimko && _po.carpimko.valeur_point_complementaire) || 11.30;

const enfants = calc.enfants || {};
const majoFamPct = enfants.majo_familiale_pct || 0;
const trimBonusEnfants = enfants.trim_bonus_total || 0;
const nbEnfants = enfants.nombre || 0;
const hasMajoFam = majoFamPct > 0;
const hasTrimBonus = trimBonusEnfants > 0;
const sexeParent = enfants.sexe_parent || 'pere';
const plafondAgircMens = enfants.plafond_majo_agirc_mensuel || 178.67;
const majoFmt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';

function buildFormulaBase(scn, sam) {
  const trimRg = scn.trimestres_rg_at_depart || 0;
  const duree = scn.duree_requise || 172;
  const taux = (scn.taux_cnav || 0) / 100;
  const ratio = trimRg / duree;
  const ratioCapped = Math.min(ratio, 1.0);
  const ratioTxt = ratio > 1.0
    ? 'min(' + trimRg + '/' + duree + '; 1) = 1,000'
    : '(' + trimRg + '/' + duree + ') = ' + fmt3(ratioCapped);
  return fmtInt(sam) + ' × ' + fmt3(taux) + ' × ' + ratioTxt + majoFmt;
}

function buildTauxDetail(scn) {
  const dec = scn.decote_pct || 0;
  const decTr = dec > 0 ? Math.round(dec / 1.25) : 0;
  if (dec > 0) {
    return '(Décote ' + fmt(dec) + ' % — ' + decTr + ' trim. manquants' + (decTr >= 20 ? ' (plafonné à 20)' : '') + ')';
  }
  if ((scn.age_depart_annees || 0) >= 67) return '(Taux Plein Automatique à 67 ans)';
  if ((scn.trimestres_acquis_tous || 0) >= (scn.duree_requise || 172)) return '(Taux Plein — durée requise atteinte)';
  return '';
}

function buildTrimDetail() {
  if (!hasTrimBonus) return '';
  const sourceTxt = sexeParent === 'mere' ? 'mère' : 'père';
  return '(dont +' + trimBonusEnfants + ' trim. ' + sourceTxt + ' — ' + nbEnfants + ' enfant' + (nbEnfants > 1 ? 's' : '') + ')';
}

const ratesPerYear = calc.points_par_an || {};

function projectionNote(scn) {
  const m = scn.mois_supplementaires_travailles || 0;
  if (m <= 0) return '';
  const y = (m / 12).toFixed(1).replace('.', ',');
  return ' <em>(estimation : ' + y + ' années de cotisations supplémentaires projetées)</em>';
}
// FIX (2026-05-21) — variante régime-aware : si le régime est dormant (rate=0),
// ne pas afficher la note "projection" qui serait trompeuse.
function projectionNoteFor(scn, regimeKey) {
  const m = scn.mois_supplementaires_travailles || 0;
  if (m <= 0) return '';
  const rate = (ratesPerYear && ratesPerYear[regimeKey] != null) ? Number(ratesPerYear[regimeKey]) : null;
  if (rate === 0) return ' <em>(régime dormant — aucune projection)</em>';
  const y = (m / 12).toFixed(1).replace('.', ',');
  return ' <em>(estimation : ' + y + ' années de cotisations supplémentaires projetées)</em>';
}

function buildCompRows(scn) {
  if (!scn || Object.keys(scn).length === 0) return '';
  const rows = [];
  const proj = projectionNote(scn); // legacy fallback (cipav, etc.)
  const projAgirc          = projectionNoteFor(scn, 'agirc');
  const projIrcantec       = projectionNoteFor(scn, 'ircantec');
  const projRci            = projectionNoteFor(scn, 'rci');
  const projCipavBase      = projectionNoteFor(scn, 'cipav_base');
  const projCipavCompl     = projectionNoteFor(scn, 'cipav_compl');

  const agPts = scn.agirc_points_projetes != null ? scn.agirc_points_projetes : 0;
  if (agPts > 0 || (scn.pension_agirc_mensuelle || 0) > 0) {
    const coeff = scn.coefficient_agirc || 1;
    const coeffNote = coeff < 1 ? ' × ' + fmt(coeff) + ' (malus 36 mois)' : '';
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) + ' (majo 3+ enfants, plafond ' + fmt(plafondAgircMens) + ' €/mois)' : '';
    const formula = fmt(agPts) + ' pts × ' + fmt4(ag_vp) + ' €' + coeffNote + majoTxt + ' / 12' + projAgirc;
    rows.push('<tr><td class="row-label">AGIRC-ARRCO<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_agirc_mensuelle) + ' € / mois</strong></td></tr>');
  }

  const ircPts = scn.ircantec_points_projetes != null ? scn.ircantec_points_projetes : 0;
  if (ircPts > 0 || (scn.pension_ircantec_mensuelle || 0) > 0) {
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) + ' (majo 3+ enfants)' : '';
    const formula = fmt(ircPts) + ' pts × ' + fmt4(ir_vp) + ' €' + majoTxt + ' / 12' + projIrcantec;
    rows.push('<tr><td class="row-label">IRCANTEC<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_ircantec_mensuelle) + ' € / mois</strong></td></tr>');
  }

  const rcPts = scn.rci_points_projetes != null ? scn.rci_points_projetes : 0;
  if (rcPts > 0 || (scn.pension_rci_mensuelle || 0) > 0) {
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';
    const formula = fmt(rcPts) + ' pts × ' + fmt4(rc_vp) + ' €' + majoTxt + ' / 12' + projRci;
    rows.push('<tr><td class="row-label">RCI / SSI (Indépendants)<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_rci_mensuelle) + ' € / mois</strong></td></tr>');
  }

  const cbPts = scn.cipav_base_points_projetes != null ? scn.cipav_base_points_projetes : 0;
  if (cbPts > 0 || (scn.pension_cipav_base_mensuelle || 0) > 0) {
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';
    const formula = fmt(cbPts) + ' pts × ' + fmt3(cipav_base_vp) + ' €' + majoTxt + ' / 12' + projCipavBase;
    rows.push('<tr><td class="row-label">CIPAV (base)<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_cipav_base_mensuelle) + ' € / mois</strong></td></tr>');
  }

  const ccPts = scn.cipav_compl_points_projetes != null ? scn.cipav_compl_points_projetes : 0;
  if (ccPts > 0 || (scn.pension_cipav_compl_mensuelle || 0) > 0) {
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';
    const formula = fmt(ccPts) + ' pts × ' + fmt(cipav_compl_vp) + ' €' + majoTxt + ' / 12' + projCipavCompl;
    rows.push('<tr><td class="row-label">CIPAV (complémentaire)<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_cipav_compl_mensuelle) + ' € / mois</strong></td></tr>');
  }

  // FIX (2026-05-21) — Affichage CARPIMKO (dédié) + boucle générique Tier 1 (CAVEC, CARMF, etc.)
  const pckbPts = scn.carpimko_base_points_projetes != null ? scn.carpimko_base_points_projetes : 0;
  if (pckbPts > 0 || (scn.pension_carpimko_base_mensuelle || 0) > 0) {
    const projCarpimkoBase = projectionNoteFor(scn, 'carpimko_base');
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';
    const formula = fmt(pckbPts) + ' pts × ' + fmt3(carpimko_base_vp) + ' €' + majoTxt + ' / 12' + projCarpimkoBase;
    rows.push('<tr><td class="row-label">CARPIMKO (base)<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_carpimko_base_mensuelle) + ' € / mois</strong></td></tr>');
  }
  const pckaPts = scn.carpimko_asv_points_projetes != null ? scn.carpimko_asv_points_projetes : 0;
  if (pckaPts > 0 || (scn.pension_carpimko_asv_mensuelle || 0) > 0) {
    const projCarpimkoAsv = projectionNoteFor(scn, 'carpimko_asv');
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';
    const formula = fmt(pckaPts) + ' pts × ' + fmt(carpimko_asv_vp) + ' €' + majoTxt + ' / 12' + projCarpimkoAsv;
    rows.push('<tr><td class="row-label">CARPIMKO (ASV)<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_carpimko_asv_mensuelle) + ' € / mois</strong></td></tr>');
  }
  const pckcPts = scn.carpimko_compl_points_projetes != null ? scn.carpimko_compl_points_projetes : 0;
  if (pckcPts > 0 || (scn.pension_carpimko_compl_mensuelle || 0) > 0) {
    const projCarpimkoCompl = projectionNoteFor(scn, 'carpimko_compl');
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';
    const formula = fmt(pckcPts) + ' pts × ' + fmt(carpimko_compl_vp) + ' €' + majoTxt + ' / 12' + projCarpimkoCompl;
    rows.push('<tr><td class="row-label">CARPIMKO (complémentaire)<span class="formula">' + formula + '</span></td><td><strong>' + fmt(scn.pension_carpimko_compl_mensuelle) + ' € / mois</strong></td></tr>');
  }

  // Tier 1 generic — itère sur tous les régimes Tier 1 calculés (CAVEC, CARMF, CARCDSF, CARPV, CAVP, CNBF, MSA, CAVAMAC, CAVOM, CRN)
  const tier1 = scn.pensions_tier1 || {};
  for (const projKey of Object.keys(tier1)) {
    const t1 = tier1[projKey] || {};
    const pts = Number(t1.points || 0);
    const pensionMens = t1.pension_mensuelle_majoree != null ? t1.pension_mensuelle_majoree : t1.pension_mensuelle_brut;
    if (pts <= 0 && (!pensionMens || pensionMens <= 0)) continue;
    // projKey format: <REGIME>_<pilier> (ex: CAVEC_base, CARMF_complementaire, CARCDSF_asv)
    const idx = projKey.lastIndexOf('_');
    const regime = idx >= 0 ? projKey.slice(0, idx) : projKey;
    const pilier = idx >= 0 ? projKey.slice(idx + 1) : '';
    const pilierLabel = pilier === 'base' ? 'base' : (pilier === 'complementaire' ? 'complémentaire' : (pilier === 'asv' ? 'ASV' : pilier));
    const projT1 = projectionNoteFor(scn, projKey);
    const majoTxt = hasMajoFam ? ' × ' + fmt(1 + majoFamPct) : '';
    const vp = Number(t1.valeur_point || 0);
    const formula = fmt(pts) + ' pts × ' + fmt(vp) + ' €' + majoTxt + ' / 12' + projT1;
    const label = pilierLabel ? regime + ' (' + pilierLabel + ')' : regime;
    rows.push('<tr><td class="row-label">' + label + '<span class="formula">' + formula + '</span></td><td><strong>' + fmt(pensionMens) + ' € / mois</strong></td></tr>');
  }

  return rows.join('');
}

function buildTotalsBlock(scn, label) {
  const brut = scn.pension_totale_brute || 0;
  const prelev = scn.prelevements_sociaux_mensuel || 0;
  const net = scn.pension_totale_nette || 0;
  const tauxPrelevPct = (calc.taux_prelevement_net || 0.091) * 100;
