         '<tr><td class="row-label">Prélèvements sociaux<span class="sublabel">(− ' + fmt(tauxPrelevPct) + ' %)</span></td><td style="color:#d9534f;">− ' + fmt(prelev) + ' € / mois</td></tr>' +
         '<tr><td class="row-label" style="color:#F39130;">TOTAL PENSION NETTE (' + label + ')</td><td class="highlight-total">~ ' + fmt(net) + ' € / mois</td></tr>';
}

function buildConsultantScenarioRows(scenarios, scn) {
  if (!scenarios || scenarios.length === 0) return '';
  const rows = ['<tr><td colspan="2" class="section-header" style="background:#fef9e7;color:#7d6608;">Dispositif retenu par le consultant</td></tr>'];
  for (const sc of scenarios) {
    const did = sc.dispositif_id || '';
    const lc = sc.last_calc || {};
    const rs = sc.result_summary || {};
    const params = sc.params || {};
    const label = sc.label || did || 'Scénario';
    let detail = '';
    let formulaPart = '';

    if (did === 'rachat_vplr') {
      // Préfère les données per-scenario (calculées dans calculScenario) sur les
      // valeurs globales du dispositif. Si le rachat est inutile dans ce
      // scénario (ex: taux plein auto 67 ans), on l'indique clairement.
      const sa = (scn && scn.vplr_rachat_applique) || null;
      const nbTrimDemande = sa ? sa.nb_trim_demande : (lc.nb_trimestres != null ? lc.nb_trimestres : (params.nb_trimestres_etudes != null ? params.nb_trimestres_etudes : (params.input != null ? params.input : 0)));
      const coutTrim = sa ? sa.cout_par_trimestre : (lc.cout_par_trimestre || 0);
      const optionLcl = sa ? sa.option : (lc.option || '');
      const optionLabel = optionLcl === 'taux_et_duree' ? 'taux + durée' : (optionLcl === 'taux_seul' ? 'taux seul' : (optionLcl || '—'));
      if (sa && !sa.utile && nbTrimDemande > 0) {
        formulaPart = nbTrimDemande + ' trim. demandés × ' + fmtInt(coutTrim) + ' € — non applicable ici (' + (sa.raison_si_inutile || 'sans effet') + ')';
        detail = '<strong style="color:#888;">Rachat sans effet — économie : ' + fmtInt(nbTrimDemande * coutTrim) + ' €</strong>';
      } else {
        const nbTrimUtile = sa ? sa.nb_trim_utile : nbTrimDemande;
        const coutTotalUtile = sa ? sa.cout_total_utile : (lc.cout_total || (nbTrimUtile * coutTrim));
        formulaPart = nbTrimUtile + ' trim. × ' + fmtInt(coutTrim || 0) + ' € = ' + fmtInt(coutTotalUtile || 0) + ' € (option ' + optionLabel + ')';
        const parts = [];
        if (sa && nbTrimUtile < nbTrimDemande) parts.push('partiellement utile (' + nbTrimUtile + ' / ' + nbTrimDemande + ' trim.)');
        const coutNet = lc.cout_net_apres_fiscalite;
        if (coutNet != null && coutNet !== (lc.cout_total || 0)) parts.push('net après fiscalité ' + fmtInt(coutNet) + ' €');
        const dureeRecup = lc.duree_recuperation_ans;
        if (dureeRecup != null) parts.push('amortissement ~' + (Math.round(Number(dureeRecup) * 10) / 10).toString().replace('.', ',') + ' ans');
        const rentable = lc.rentable;
        if (rentable === true) parts.push('rentable');
        else if (rentable === false) parts.push('non rentable');
        detail = parts.length > 0 ? '<strong>' + parts.join(' — ') + '</strong>' : '';
      }
    } else if (did === 'racl') {
      const eligible = rs.eligible != null ? rs.eligible : lc.eligible;
      const ageAnt = lc.age_depart_anticipe != null ? lc.age_depart_anticipe : rs.age_depart_anticipe;
      const dateAnt = lc.date_depart_anticipe || rs.date_depart_anticipe;
      formulaPart = eligible ? 'Carrière longue éligible' : 'Carrière longue non éligible';
      const parts = [];
      if (ageAnt != null) parts.push('départ à ' + ageAnt + ' ans');
      if (dateAnt) parts.push(fmtDateLong(dateAnt));
      detail = parts.length > 0 ? '<strong>' + parts.join(' — ') + '</strong>' : '';
    } else if (did === 'chomage_ind' || did === 'chomage_non_ind') {
      const nbAssim = lc.trimestres_assimiles != null ? lc.trimestres_assimiles : rs.trimestres_assimiles;
      const eligible = rs.eligible != null ? rs.eligible : lc.eligible;
      const dureeMois = params.duree_mois || params.input;
      formulaPart = (dureeMois ? dureeMois + ' mois de chômage' : 'Chômage déclaré');
      detail = nbAssim != null
        ? '<strong>+' + nbAssim + ' trim. assimilés' + (eligible === false ? ' (non éligible)' : '') + '</strong>'
        : (eligible === true ? '<strong>Éligible</strong>' : (eligible === false ? '<strong>Non éligible</strong>' : ''));
    } else if (did === 'retraite_progressive') {
      const quotite = params.quotite_activite != null ? params.quotite_activite : params.input;
      const eligible = rs.eligible != null ? rs.eligible : lc.eligible;
      const pensionPart = lc.pension_partielle_mensuelle;
      formulaPart = quotite != null ? 'Quotité activité ' + quotite + ' %' : 'Retraite progressive';
      const parts = [];
      if (pensionPart != null) parts.push('pension partielle ' + fmt(pensionPart) + ' €/mois');
      if (eligible === false) parts.push('non éligible');
      detail = parts.length > 0 ? '<strong>' + parts.join(' — ') + '</strong>' : (eligible === true ? '<strong>Éligible</strong>' : '');
    } else if (did === 'cumul_emploi') {
      const eligible = rs.eligible != null ? rs.eligible : lc.eligible;
      const typeCumul = lc.type_cumul || rs.type_cumul;
      formulaPart = 'Cumul emploi-retraite';
      detail = eligible
        ? '<strong>' + (typeCumul ? typeCumul : 'Éligible') + ' — possibilité de 2e pension</strong>'
        : '<strong>Non éligible</strong>';
    } else if (did === 'arret_activite') {
      const dateArret = params.date_arret || params.input || lc.date_arret;
      formulaPart = 'Arrêt d\'activité';
      detail = dateArret ? '<strong>Cessation au ' + fmtDateCourt(dateArret) + '</strong>' : '';
    } else if (did === 'cotisations_min') {
      const eligible = rs.eligible != null ? rs.eligible : lc.eligible;
      formulaPart = 'Cotisations minimales (TI/TNS)';
      detail = eligible ? '<strong>Maintien validation 4 trim./an</strong>' : '<strong>Non applicable</strong>';
    } else {
      const eligible = rs.eligible != null ? rs.eligible : lc.eligible;
      formulaPart = label;
      detail = eligible === true ? '<strong>Éligible</strong>' : (eligible === false ? '<strong>Non éligible</strong>' : '');
    }

    rows.push('<tr><td class="row-label">' + label + '<span class="formula">' + formulaPart + '</span></td><td>' + (detail || '—') + '</td></tr>');
  }
  return rows.join('');
}

function buildScenarioBlock(scn, hypoLabel, age, dateLabel, taxClass, tauxDetail, formulaBase, cnavAn, consultantScenarios) {
  return '<tr><td colspan="2" class="section-header">' + hypoLabel + ' (' + age + ') — ' + dateLabel + '</td></tr>' +
         '<tr><td class="row-label">Trimestres Acquis / Requis<span class="sublabel">' + buildTrimDetail() + '</span></td><td>' + (scn.trimestres_acquis_tous || '') + ' / ' + (scn.duree_requise || 172) + '</td></tr>' +
         '<tr><td class="row-label">Salaire Annuel Moyen (SAM)</td><td class="sam-value">' + fmtInt(samAnnuel) + ' €</td></tr>' +
         '<tr><td class="row-label">Taux Retenu (Base)<span class="sublabel">' + tauxDetail + '</span></td><td class="' + taxClass + '">' + fmt(scn.taux_cnav) + ' %</td></tr>' +
         '<tr><td class="row-label">Calcul Retraite de Base<span class="formula">SAM × Taux × ratio' + (hasMajoFam ? ' × 1,10 (majo)' : '') + '</span></td><td><span class="formula">' + formulaBase + '</span><strong>~ ' + cnavAn + ' € / an (~ ' + fmt(scn.pension_cnav_mensuelle || 0) + ' € / mois)</strong></td></tr>' +
         buildCompRows(scn) +
