const H1_BLOCK = buildScenarioBlock(H1, _h1ConsultantLabel, h1AgeLabel, fmtDateLong(H1.date_depart), tauxClass(H1), buildTauxDetail(H1), buildFormulaBase(H1, samAnnuel), fmtInt((H1.pension_cnav_mensuelle || 0) * 12), _prepScenarios);
