  if (scenariosRetenus.length > 0) {
    h += '<thead><tr><th>Scénario sélectionné</th><th style="width:35%;">Détail</th></tr></thead><tbody>';
    for (const s of scenariosRetenus) {
      const lc = s.last_calc || {};
      const eligible = (s.result_summary && s.result_summary.eligible !== undefined)
        ? (s.result_summary.eligible ? 'Éligible' : 'Non éligible')
        : '';
      const montant = lc.pension_mensuelle_nette || lc.pension_totale_nette || lc.montant_mensuel || lc.montant || null;
      const parts = [];
      if (eligible) parts.push(eligible);
      if (montant)  parts.push('~ ' + Math.round(Number(montant)).toLocaleString('fr-FR') + ' €/mois');
      const detail = parts.length ? parts.join(' — ') : '—';
